import React from "react";

import {AppBar} from "@mui/material";
import {Toolbar, Tabs, Tab, Button } from "@mui/material";
import AccountCircleIcon from '@mui/icons-material/AccountCircle';
import { NavLink } from "react-router-dom";
import logo from "../assets/logo.svg";
import DrawerComp from "./Drawer";
import useMediaQuery from "@mui/material/useMediaQuery";
import { useTheme } from "@mui/material/styles";



function Nav() {

  const theme = useTheme();
  const isMatch = useMediaQuery (theme.breakpoints.down('md')); //true when md and lower

  return (
    <AppBar position="static">
    <Toolbar>
      
      <img src={logo} width="80px" />
{/* Conditional (ternary) operator like if condition ? (do this):(do this) */}      
    { 
    isMatch ? (  
      <DrawerComp />

    ):(

    <>
      <Tabs>
        <NavLink to="/"> <Tab label ="Home" textColor="primary" /></NavLink>
        <NavLink to="/menu"> <Tab label="Menu" textColor="primary" /></NavLink>
        <NavLink to="/team"><Tab label="Team"  textColor="primary" /></NavLink>
      </Tabs>

      <Button sx={{marginLeft: "auto"}} variant="contained">
       <AccountCircleIcon /> Log in
      </Button>
      </>
    )
}
    </Toolbar>
     
    
    </AppBar>
  );
}

export default Nav;
